Translate the following GNU C++14 code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include<bits/stdc++.h>
using namespace std;
#define int long long
const int mod1=998244353;
const int mod2=1e9+7;
int ans;
int n;
int cnt1;
vector<int> val[7];
int sum[7];
void dfs1(int k1,int k2){
	if(k1==7)return;
	val[k1].push_back((cnt1-k2+mod1)%mod1);
	sum[k1]+=(cnt1-k2+mod1)%mod1;
	cnt1++;
	for(int i=0;i<=9;++i){
		dfs1(k1+1,k2*10+i);
	}
}
bool check(int x){
	const int half=1000000;
	return x*half+999999<=n&&x*half*10>n;
}
int cnt2;
int poww[7]={1,10,100,1000,10000,100000,1000000};
void dfs2(int k1,int k2){
	if(k2>n)return;
	if(check(k2)){
		for(int i=0;i<=6;++i){
			int offset=((cnt2+1-(k2*poww[i]))%mod1+mod1)%mod1;
			int pos=lower_bound(val[i].begin(),val[i].end(),mod1-offset)-val[i].begin();
			(ans+=(sum[i]+offset*val[i].size()-mod1*(val[i].size()-pos)))%=mod2;
		}
		cnt2+=cnt1;
	}
	else {
		cnt2++;
		(ans+=((cnt2-k2)%mod1+mod1)%mod1)%=mod2;
		for(int i=(!k1);i<=9;++i){
			dfs2(k1+1,k2*10+i);
		}
	}
}
signed main(){
	FILE* f=stdin;
	fscanf(f,"%lld",&n);
	dfs1(0,0);
	for(int i=0;i<=6;++i)sort(val[i].begin(),val[i].end());
	cnt2=-1;
	dfs2(0,0);
	fprintf(f,"%lld\n",ans);
}
</original_code>
